package com.neu.riketiku.zhishikapian;
import com.neu.riketiku.renzheng.RenZhengYongHu;import jakarta.validation.Valid;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/student/knowledge-cards") public class KnowledgeCardStudentController{private final KnowledgeCardService service;public KnowledgeCardStudentController(KnowledgeCardService service){this.service=service;}@GetMapping public List<KnowledgeCardDtos.Card>list(@AuthenticationPrincipal RenZhengYongHu u,@RequestParam(required=false)Long subjectId,@RequestParam(required=false)Long knowledgePointId,@RequestParam(required=false)String type,@RequestParam(required=false)Boolean favorite,@RequestParam(required=false)String mastery){return service.studentList(u.id(),subjectId,knowledgePointId,type,favorite,mastery);}@PutMapping("/{id}/state")public KnowledgeCardDtos.Card state(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id,@Valid@RequestBody KnowledgeCardDtos.State r){return service.state(u.id(),id,r);}@GetMapping("/{id}/frequency")public List<KnowledgeCardDtos.Frequency>frequency(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id){return service.frequency(u.id(),id);}@GetMapping("/{id}/attachments/{attachmentId}/content")public org.springframework.http.ResponseEntity<byte[]> content(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id,@PathVariable long attachmentId){var image=service.content(u.id(),id,attachmentId,false);return org.springframework.http.ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).contentType(org.springframework.http.MediaType.parseMediaType(image.mime())).body(image.bytes());}}
